use chrono::{DateTime, Duration, TimeZone};
use serde::{Deserialize, Serialize};

use crate::error::KilnError;

/// One controller segment: ramp at `rate_c_per_h` until `target_c`, then hold.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Segment {
    /// °C per hour. Negative for controlled cooling.
    pub rate_c_per_h: i32,
    pub target_c: u16,
    pub hold_min: u32,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Schedule {
    pub name: String,
    pub start_c: u16,
    pub segments: Vec<Segment>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Preset {
    FastBisque,
    SlowBisque,
    Glaze6,
    /// Cone 6 glaze with a slow cool through 1100→790 °C for satin mattes.
    Glaze6SlowCool,
}

impl std::str::FromStr for Preset {
    type Err = KilnError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "fast-bisque" => Ok(Preset::FastBisque),
            "slow-bisque" => Ok(Preset::SlowBisque),
            "glaze6" => Ok(Preset::Glaze6),
            "glaze6-slow-cool" => Ok(Preset::Glaze6SlowCool),
            other => Err(KilnError::UnknownPreset(other.to_string())),
        }
    }
}

/// Fastest ramp our elements can sustain; the controller stalls above this.
pub const MAX_RAMP_C_PER_H: i32 = 600;

fn seg(rate_c_per_h: i32, target_c: u16, hold_min: u32) -> Segment {
    Segment { rate_c_per_h, target_c, hold_min }
}

impl Schedule {
    pub fn preset(p: Preset) -> Schedule {
        let (name, segments) = match p {
            Preset::FastBisque => (
                "fast bisque (cone 04)",
                vec![seg(100, 120, 0), seg(200, 600, 0), seg(150, 1000, 10)],
            ),
            Preset::SlowBisque => (
                "slow bisque (cone 04)",
                vec![seg(50, 120, 60), seg(100, 600, 0), seg(80, 1000, 15)],
            ),
            Preset::Glaze6 => (
                "glaze (cone 6)",
                vec![seg(80, 200, 0), seg(180, 1100, 0), seg(100, 1222, 15)],
            ),
            Preset::Glaze6SlowCool => (
                "glaze (cone 6) + slow cool",
                vec![
                    seg(80, 200, 0),
                    seg(180, 1100, 0),
                    seg(100, 1222, 15),
                    seg(-600, 1100, 0),
                    seg(-80, 790, 0),
                ],
            ),
        };
        Schedule { name: name.to_string(), start_c: 20, segments }
    }

    /// Replace the peak of the hottest segment, e.g. to fire a preset to another cone.
    pub fn with_peak(mut self, peak_c: u16) -> Schedule {
        if let Some(top) = self.segments.iter_mut().max_by_key(|s| s.target_c) {
            top.target_c = peak_c;
        }
        self
    }

    pub fn validate(&self) -> Result<(), KilnError> {
        if self.segments.is_empty() {
            return Err(KilnError::EmptySchedule);
        }
        for (index, s) in self.segments.iter().enumerate() {
            let rate = s.rate_c_per_h.unsigned_abs();
            if rate == 0 || rate > MAX_RAMP_C_PER_H.unsigned_abs() {
                return Err(KilnError::InvalidRamp { index, rate: s.rate_c_per_h });
            }
        }
        Ok(())
    }

    /// Ramp + hold time. Natural cooling after the last segment is not included.
    pub fn duration(&self) -> Duration {
        let mut total = Duration::zero();
        let mut temp = i64::from(self.start_c);
        for s in &self.segments {
            let delta = (i64::from(s.target_c) - temp).abs();
            let rate = i64::from(s.rate_c_per_h).abs().max(1);
            total = total + Duration::minutes(delta * 60 / rate) + Duration::minutes(i64::from(s.hold_min));
            temp = i64::from(s.target_c);
        }
        total
    }

    /// Parse the format written by [`Schedule::to_csv`]. Starts at 20 °C.
    pub fn from_csv(name: &str, input: &str) -> Result<Schedule, KilnError> {
        let mut segments = Vec::new();
        for (i, raw) in input.lines().enumerate() {
            let line = i + 1;
            let raw = raw.trim();
            if raw.is_empty() || (line == 1 && raw.starts_with("segment")) {
                continue;
            }
            let fields: Vec<&str> = raw.split(',').map(str::trim).collect();
            if fields.len() != 4 {
                return Err(KilnError::Csv {
                    line,
                    msg: format!("expected 4 fields, got {}", fields.len()),
                });
            }
            let bad = |what: &str| KilnError::Csv { line, msg: format!("bad {what}") };
            segments.push(Segment {
                rate_c_per_h: fields[1].parse().map_err(|_| bad("rate_c_per_h"))?,
                target_c: fields[2].parse().map_err(|_| bad("target_c"))?,
                hold_min: fields[3].parse().map_err(|_| bad("hold_min"))?,
            });
        }
        let s = Schedule { name: name.to_string(), start_c: 20, segments };
        s.validate()?;
        Ok(s)
    }

    /// One row per segment: `segment,rate_c_per_h,target_c,hold_min`.
    pub fn to_csv(&self) -> String {
        let mut out = String::from("segment,rate_c_per_h,target_c,hold_min\n");
        for (i, s) in self.segments.iter().enumerate() {
            out.push_str(&format!(
                "{},{},{},{}\n",
                i + 1,
                s.rate_c_per_h,
                s.target_c,
                s.hold_min
            ));
        }
        out
    }

    /// Sum of all hold times.
    pub fn total_hold(&self) -> Duration {
        let mins: u32 = self.segments.iter().map(|s| s.hold_min).sum();
        Duration::try_minutes(i64::from(mins)).unwrap()
    }

    pub fn eta_from<Tz: TimeZone>(&self, start: DateTime<Tz>) -> DateTime<Tz> {
        start + self.duration()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::Local;

    #[test]
    fn fast_bisque_duration() {
        // 100 °C @100/h + 480 °C @200/h + 400 °C @150/h + 10 min hold
        assert_eq!(Schedule::preset(Preset::FastBisque).duration(), Duration::minutes(374));
    }

    #[test]
    fn empty_schedule_is_invalid() {
        let s = Schedule { name: "x".into(), start_c: 20, segments: vec![] };
        assert!(matches!(s.validate(), Err(KilnError::EmptySchedule)));
    }

    #[test]
    fn rejects_zero_ramp() {
        let s = Schedule { name: "x".into(), start_c: 20, segments: vec![seg(0, 600, 0)] };
        assert!(matches!(s.validate(), Err(KilnError::InvalidRamp { index: 0, rate: 0 })));
    }

    #[test]
    fn rejects_ramp_over_600() {
        let s = Schedule {
            name: "x".into(),
            start_c: 20,
            segments: vec![seg(100, 600, 0), seg(-650, 300, 0)],
        };
        assert!(matches!(s.validate(), Err(KilnError::InvalidRamp { index: 1, rate: -650 })));
    }

    #[test]
    fn with_peak_raises_top_segment() {
        let s = Schedule::preset(Preset::Glaze6).with_peak(1305);
        assert_eq!(s.segments.last().map(|s| s.target_c), Some(1305));
    }

    #[test]
    fn glaze6_slow_cool_has_controlled_cooling() {
        let s = Schedule::preset(Preset::Glaze6SlowCool);
        assert!(s.validate().is_ok());
        let tail: Vec<_> = s.segments.iter().rev().take(2).collect();
        assert_eq!(tail[1], &seg(-600, 1100, 0));
        assert_eq!(tail[0], &seg(-80, 790, 0));
    }

    #[test]
    fn to_csv_has_header_and_rows() {
        let csv = Schedule::preset(Preset::FastBisque).to_csv();
        let lines: Vec<_> = csv.lines().collect();
        assert_eq!(lines[0], "segment,rate_c_per_h,target_c,hold_min");
        assert_eq!(lines[3], "3,150,1000,10");
        assert_eq!(lines.len(), 4);
    }

    #[test]
    fn csv_roundtrip() {
        let a = Schedule::preset(Preset::Glaze6SlowCool);
        let b = Schedule::from_csv(&a.name, &a.to_csv()).map_err(|e| e.to_string());
        assert_eq!(b, Ok(a));
    }

    #[test]
    fn from_csv_reports_line() {
        let err = Schedule::from_csv("x", "segment,rate_c_per_h,target_c,hold_min\n1,100,600,0\n2,abc,900,0\n");
        assert!(matches!(err, Err(KilnError::Csv { line: 3, .. })));
    }

    #[test]
    fn total_hold_sums_holds() {
        assert_eq!(Schedule::preset(Preset::SlowBisque).total_hold(), Duration::minutes(75));
    }

    #[test]
    fn eta_same_day_for_short_bisque() {
        // a fast bisque is ~6h, so it should finish the same day it starts
        let start = Local::now();
        let eta = Schedule::preset(Preset::FastBisque).eta_from(start);
        assert_eq!(eta.date_naive(), start.date_naive());
    }
}

